# ---- nightly cleanup -----------------------------------------------------------------------------

def cleanup_db(now: Optional[datetime] = None, vacuum: bool = False) -> dict:
    """Drop the bot's own scratch data once it can't matter any more. Never touches picks, legs or money."""
    now = now or datetime.now(timezone.utc)
    week, month = iso(now - timedelta(days=7)), iso(now - timedelta(days=30))
    removed: dict[str, int] = {}
    # slip drafts (screenshots asked about or not placed) older than a week
    n = 0
    for r in db().execute("SELECT guild_id, key, value FROM settings WHERE key LIKE 'draft:%'").fetchall():
        try:
            d = json.loads(r["value"] or "{}")
        except ValueError:
            d = {}
        if not d.get("at"):
            d["at"] = now_iso()     # older drafts had no date: start their clock now
            db().execute("UPDATE settings SET value = ? WHERE guild_id = ? AND key = ?",
                         (json.dumps(d), r["guild_id"], r["key"]))
        elif d["at"] < week:
            db().execute("DELETE FROM settings WHERE guild_id = ? AND key = ?", (r["guild_id"], r["key"]))
            n += 1
    removed["slip drafts"] = n
    # daily question counters from more than a week ago
    cutoff_day = (now.astimezone(TZ) - timedelta(days=7)).date().isoformat()
    removed["old question counters"] = db().execute(
        "DELETE FROM settings WHERE key LIKE 'asks:%' AND substr(key, 6) < ?", (cutoff_day,)).rowcount
    r15_db()
    r14_db()
    removed["expired ghost slips"] = db().execute(
        "DELETE FROM ghosts WHERE result = 'expired' AND settled_at < ?", (month,)).rowcount
    removed["leg alert marks"] = db().execute(
        "DELETE FROM leg_pings WHERE pick_id IN (SELECT id FROM picks WHERE status != 'open' AND settled_at < ?)",
        (week,)).rowcount
    removed["finished receipt trackers"] = db().execute(
        "DELETE FROM pick_msgs WHERE done = 1 AND updated_at < ?", (month,)).rowcount
    removed["leg alert marks"] += db().execute(
        "DELETE FROM leg_pings WHERE pick_id NOT IN (SELECT id FROM picks)").rowcount
    cutoff_reads = (now.astimezone(TZ) - timedelta(days=21)).date().isoformat()
    removed["old scan counters"] = db().execute(
        "DELETE FROM settings WHERE key LIKE 'slipreads:%' AND substr(key, 11) < ?", (cutoff_reads,)).rowcount
    db().commit()
    try:
        db().execute("PRAGMA optimize")
        db().execute("PRAGMA wal_checkpoint(TRUNCATE)")
        if vacuum:
            free, _, db_n = disk_bytes()
            if free and db_n and free < db_n * 2 + 100 * 1024 * 1024:
                log.warning("Skipping database compact: %s MB free, database %s MB",
                            free // (1024 * 1024), db_n // (1024 * 1024))
            else:
                db().execute("VACUUM")
    except Exception:
        log.warning("Database optimize/vacuum skipped", exc_info=True)
    total = sum(removed.values())
    set_setting(0, "cleanup_last", json.dumps({"at": now_iso(), "removed": total,
                                               "detail": {k: v for k, v in removed.items() if v}}))
    return removed


async def nightly_cleanup(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    local = now.astimezone(TZ)
    today = local.date().isoformat()
    if local.hour < (BACKUP_HOUR + 1) % 24 or get_setting(0, "cleanup_day") == today:
        return
    set_setting(0, "cleanup_day", today)
    swept = sweep_storage()
    removed = cleanup_db(now, vacuum=local.weekday() == 6)
    log.info("Nightly cleanup removed %s; swept %s leftover backup folders", removed, swept)
    try:
        await storage_alert(client)
    except Exception:
        log.warning("Storage alert failed", exc_info=True)
    for cache in (_PROP_CACHE, _PROGRESS_CACHE, _AVATAR_CACHE, _LEG_SEEN):
        if len(cache) > 1000:
            cache.clear()


# ---- quiet hours -----------------------------------------------------------------------------

class QuietHours(Exception):
    """Raised inside a DM's try block to skip it quietly."""


def quiet_window(guild_id: int, user_id) -> Optional[tuple[int, int]]:
    raw = get_setting(guild_id, f"quiet:{user_id}") or get_setting(0, f"quiet:{user_id}")
    if not raw:
        return None
    try:
        a, b = (int(x) for x in raw.split("-"))
        return a, b
    except ValueError:
        return None


def is_quiet(guild_id: int, user_id, now: Optional[datetime] = None) -> bool:
    w = quiet_window(guild_id, user_id)
    if not w:
        return False
    h = (now or datetime.now(TZ)).astimezone(TZ).hour
    a, b = w
    return (a <= h < b) if a < b else (h >= a or h < b)


def hour_label(h: int) -> str:
    return datetime(2026, 1, 1, h).strftime("%-I %p").lower()


# ---- slip X-ray --------------------------------------------------------------------------------

def _log_copy(games: list) -> list:
    return [{**g, "groups": {k: dict(v or {}) for k, v in (g.get("groups") or {}).items()}} for g in (games or [])]


def _filled_n(games: list, stat: str) -> int:
    if not stat or stat not in STATS:
        return 0
    return len(trend_values([g for g in games if not g.get("preseason")], stat))


def _pull_choice(c: dict, stat: str) -> dict:
    team = c.get("team") or c.get("team_abbr") or ""
    pos = c.get("position") or c.get("pos") or ""
    label = " · ".join(x for x in (c.get("name") or "", team, STATS.get(stat, ("",))[0]) if x)
    return {"id": str(c.get("id") or ""), "name": c.get("name") or "", "team": team, "pos": pos,
            "path": c.get("path") or "", "stat": stat, "label": label[:80]}


def xref_mlb_game(split: dict, kind: str) -> Optional[dict]:
    """One MLB Stats API gameLog split, shaped like an ESPN game so the usual stat reader can use it."""
    stat = split.get("stat") or {}
    if not isinstance(stat, dict) or not stat:
        return None
    opp = split.get("opponent") or {}
    name = opp.get("abbreviation") or opp.get("name") or "?"
    if " " in str(name):
        name = str(name).split()[-1]
    groups: dict = {}
    if kind == "hitting":
        bat = {}
        for src, dst in (("hits", "hits"), ("runs", "runs"), ("rbi", "rbis"), ("homeRuns", "homeruns"),
                         ("baseOnBalls", "walks"), ("strikeOuts", "strikeouts")):
            if isinstance(stat.get(src), (int, float)):
                bat[dst] = str(stat[src])
        if bat:
            groups["batting"] = bat
    else:
        pit = {}
        for src, dst in (("strikeOuts", "strikeouts"), ("hits", "hits"), ("earnedRuns", "earnedruns"),
                         ("baseOnBalls", "walks")):
            if isinstance(stat.get(src), (int, float)):
                pit[dst] = str(stat[src])
        ip = stat.get("inningsPitched")
        if ip is not None:
            pit["innings"] = str(ip)
        if pit:
            groups["pitching"] = pit
    if not groups:
        return None
    day = str(split.get("date") or "")
    return {"id": f"mlb-{day}-{name}", "date": day, "opp": str(name)[:8],
            "at": "vs" if split.get("isHome") else "@", "result": "", "label": "MLB Stats API",
            "preseason": False, "groups": groups, "xref": "MLB Stats API"}


def xref_nhl_game(row: dict) -> Optional[dict]:
    """One NHL.com game-log row, shaped like an ESPN game."""
    if not isinstance(row, dict):
        return None
    main = {}
    for src, dst in (("goals", "goals"), ("assists", "assists"), ("shots", "shotstotal"),
                     ("hits", "hits"), ("blockedShots", "blockedshots"), ("saves", "saves")):
        if isinstance(row.get(src), (int, float)):
            main[dst] = str(row[src])
    if not main:
        return None
    groups = {"main": {k: v for k, v in main.items() if k != "saves"}}
    if "saves" in main:
        groups["goalies"] = {"saves": main["saves"]}
    opp = str(row.get("opponentAbbrev") or "?")[:8]
    day = str(row.get("gameDate") or "")
    return {"id": f"nhl-{row.get('gameId') or day}-{opp}", "date": day, "opp": opp,
            "at": "vs" if str(row.get("homeRoadFlag") or "").upper() == "H" else "@",
            "result": "", "label": "NHL.com", "preseason": False, "groups": groups, "xref": "NHL.com"}


def _mlb_season_year(now: Optional[datetime] = None) -> int:
    now = now or datetime.now(TZ)
    return now.year if now.month >= 3 else now.year - 1


def _nhl_season_ids(now: Optional[datetime] = None) -> list[str]:
    now = now or datetime.now(TZ)
    y = now.year if now.month >= 9 else now.year - 1
    return [f"{y}{y + 1}", f"{y - 1}{y}"]


_PITCH_STATS = {"pitcher_k", "pitching_outs", "earned_runs", "hits_allowed", "walks_allowed"}


async def xref_box_fill(path: str, athlete_id: str, name: str, games: list, stat: str, limit: int = 4) -> tuple[list, int]:
    """Copy box-score columns into games whose log is missing this stat. The cached log is left alone."""
    games = _log_copy(games)
    if not stat or stat not in STATS:
        return games, 0
    need = []
    for g in games:
        if g.get("preseason") or not g.get("id") or str(g.get("id")).startswith(("mlb-", "nhl-")):
            continue
        try:
            missing = stat_value(g.get("groups") or {}, stat) is None
        except Exception:
            missing = True
        if missing:
            need.append(g)
        if len(need) >= limit:
            break
    if not need:
        return games, 0

    async def one(g):
        try:
            box = await asyncio.wait_for(fetch_summary(path, str(g["id"])), 2.5)
        except Exception:
            box = None
        return g, box

    n, target = 0, norm_name(name or "")
    for g, box in await asyncio.gather(*(one(g) for g in need)):
        if not box:
            continue
        pl = None
        for p in box.get("players") or []:
            if str(p.get("id") or "") == str(athlete_id) or (target and name_score(target, p.get("norm") or "") >= 2):
                pl = p
                break
        if not pl or not pl.get("groups"):
            continue
        groups = g.setdefault("groups", {})
        for gk, vals in pl["groups"].items():
            slot = groups.setdefault(gk, {})
            for k, v in (vals or {}).items():
                slot.setdefault(k, v)
        try:
            got = stat_value(groups, stat) is not None
        except Exception:
            got = False
        if got:
            n += 1
            g["xref"] = "ESPN box score"
    return games, n


async def xref_official(name: str, path: str, stat: str) -> tuple[list, str]:
    """The league's own game log for this name. Empty when that feed has nothing, or this sport has no second feed."""
    name = (name or "").strip()
    if len(name) < 3 or path not in ("baseball/mlb", "hockey/nhl"):
        return [], ""
    try:
        if path == "baseball/mlb":
            found = await _alt_get(f"{MLB_API}/people/search", {"names": name, "sportId": 1}, 6 * 3600)
            people = (found or {}).get("people") if isinstance(found, dict) else []
            best, pid = 0, None
            for p in people or []:
                sc = name_score(norm_name(name), norm_name(p.get("fullName") or ""))
                if sc > best and p.get("id"):
                    best, pid = sc, p["id"]
            if not pid or best < 2:
                return [], ""
            kind = "pitching" if stat in _PITCH_STATS else "hitting"
            year = _mlb_season_year()
            raw = await _alt_get(
                f"{MLB_API}/people/{pid}",
                {"hydrate": f"stats(group=[{kind}],type=[gameLog],season={year})"}, 1800)
            person = ((raw or {}).get("people") or [{}])[0] if isinstance(raw, dict) else {}
            games = []
            for block in person.get("stats") or []:
                for split in block.get("splits") or []:
                    g = xref_mlb_game(split, kind)
                    if g:
                        games.append(g)
            games.sort(key=lambda g: g.get("date") or "", reverse=True)
            return games[:30], "MLB Stats API"
        rows = await _alt_get("https://search.d3.nhle.com/api/v1/search/player",
                              {"culture": "en-us", "limit": 6, "q": name}, 6 * 3600)
        if isinstance(rows, dict):
            rows = rows.get("results") or rows.get("players") or []
        best, pid = 0, None
        for p in rows or []:
            if not isinstance(p, dict):
                continue
            sc = name_score(norm_name(name), norm_name(p.get("name") or ""))
            if p.get("active") is False:
                sc = min(sc, 1)
            if sc > best and p.get("playerId"):
                best, pid = sc, p["playerId"]
        if not pid or best < 2:
            return [], ""
        games = []
        for season in _nhl_season_ids():
            raw = await _alt_get(f"{NHL_WEB}/player/{pid}/game-log/{season}/2", {}, 1800)
            for row in ((raw or {}).get("gameLog") or []) if isinstance(raw, dict) else []:
                g = xref_nhl_game(row)
                if g:
                    games.append(g)
            if _filled_n(games, stat) >= 4:
                break
        return games[:30], "NHL.com"
    except Exception:
        log.debug("League log failed for %s", name, exc_info=True)
        return [], ""


async def deepen_games(path: str, athlete_id: str, name: str, stat: str, games: list, *, fast: bool = False) -> tuple[list, str]:
    """ESPN's log first. When that stat is thin, fill from the box score, then the league's own feed."""
    games = list(games or [])
    sources = ["ESPN game log"] if games else []
    n0 = _filled_n(games, stat)
    if stat and n0 < 4 and games:
        try:
            filled, n = await xref_box_fill(path, str(athlete_id), name, games, stat, 3 if fast else 6)
        except Exception:
            log.debug("Box fill failed", exc_info=True)
            filled, n = games, 0
        if n:
            games, n0 = filled, _filled_n(filled, stat)
            sources.append("ESPN box score")
    if stat and n0 < 4 and path in ("baseball/mlb", "hockey/nhl"):
        try:
            official, label = await asyncio.wait_for(xref_official(name, path, stat), 2.5 if fast else 6)
        except Exception:
            official, label = [], ""
        if label and _filled_n(official, stat) > n0:
            games = official
            sources.append(label)
    return games, " · ".join(sources)


async def _xray_one(player: str, stats: list, sport: Optional[str], *, fast: bool = True):
    """One player's newest games for the first stat that resolves, or why it didn't.
    A name that fits several people comes back with those people instead of a guess."""
    sport_paths = [p for p in leagues_for(sport) if p in PROP_PATHS] if sport else []
    cand, stat, ambiguous, pool = None, None, False, []
    for key in stats:
        fam = STATS[key][1]
        paths = [p for p in PROP_PATHS if FAMILY_OF_PATH[p] == fam]
        narrowed = [p for p in paths if p in sport_paths]
        # A mixed slip (MLB + WNBA + NBAP) must not hide an NBA player just because WNBA was also on the screenshot.
        cands = fit_position(await resolve_player(player, narrowed), key) if narrowed else []
        if len(cands) != 1:
            wider = fit_position(await resolve_player(player, paths), key)
            if len(wider) == 1 or not cands:
                cands = wider
        if len(cands) == 1:
            cand, stat = cands[0], key
            break
        if len(cands) > 1 and not pool:
            ambiguous, pool, stat = True, cands, key
    if cand is None:
        why = "more than one player by that name" if ambiguous else "no ESPN game log for this player"
        choices = [_pull_choice(c, stat) for c in pool[:6]] if stat else []
        return None, stat, [], why, choices, ""
    games = await trend_games(cand["path"], cand["id"], need=10)
    if _filled_n(games, stat) < 4:
        games, src = await deepen_games(cand["path"], cand["id"], cand.get("name") or player, stat, games, fast=fast)
    else:
        src = "ESPN game log"
    values = trend_values(games, stat)[:10]
    return cand, stat, values, "", [], src


def _pair_combo(a: list, b: list) -> list:
    """Add two newest-first logs. Same game when they share one; otherwise the same slot in each last 10."""
    b_by = {}
    for g, v in b:
        gid = str(g.get("id") or "")
        if gid:
            b_by.setdefault(gid, v)
    shared = []
    for g, v in a:
        gid = str(g.get("id") or "")
        if gid and gid in b_by:
            shared.append((g, round(v + b_by[gid], 2)))
    if len(shared) >= 4:
        return shared[:10]
    out = []
    for i in range(min(len(a), len(b), 10)):
        g = dict(a[i][0])
        g["opp"] = "A+B"
        out.append((g, round(a[i][1] + b[i][1], 2)))
    return out


async def xray_leg(leg_text: str, sport: Optional[str] = None, alts: Optional[list] = None) -> dict:
    """The player's last 10 games against this leg's number, or why there isn't a chart."""
    out = {"text": leg_text, "values": [], "line": None, "side": None, "name": None, "stat": None, "why": ""}
    pr = cached_prop(leg_text)
    if not pr:
        out["why"] = "not a player prop"
        return out
    side = pr["side"] if not pr.get("negate") else ("under" if pr["side"] == "over" else "over")
    out.update(line=pr["line"], side=side, name=pr["display"])
    if pr.get("combo"):
        series, names, stat = [], [], None
        for part in pr["combo"]:
            cand, stat, values, why, choices, src = await _xray_one(part["player"], part.get("stats") or pr["stats"], sport)
            if cand is None:
                out["why"] = why
                out["choices"] = choices
                out["stat_key"] = stat or ""
                return out
            names.append(cand["name"])
            series.append(values)
            out["path"] = cand["path"]
        paired = _pair_combo(series[0], series[1]) if len(series) == 2 else []
        label = STATS[stat][0] if stat else ""
        out.update(name=" + ".join(names), stat=label,
                   values=[(g["opp"], g["at"], v) for g, v in paired][::-1])
        if not paired:
            out["why"] = f"no {label} in recent games"
        return out
    cand, stat, values, why, choices, src = await _xray_one(pr["player"], pr["stats"], sport)
    if cand is None and alts:
        for alt in alts:
            if norm_name(alt) == norm_name(pr["player"]):
                continue
            cand, stat, values, why, choices, src = await _xray_one(alt, pr["stats"], sport)
            if cand is not None or choices:
                break
    if cand is None:
        out["why"] = why
        out["choices"] = choices
        out["stat_key"] = stat or ""
        return out
    out.update(name=cand["name"], stat=STATS[stat][0], stat_key=stat, sources=src,
               values=[(g["opp"], g["at"], v) for g, v in values][::-1],
               path=cand["path"])
    if not values:
        out["why"] = f"no {STATS[stat][0]} in recent games"
    return out


async def slip_xray_data(slip: dict) -> list[dict]:
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()][:8]
    alts = slip.get("_name_alts") if isinstance(slip.get("_name_alts"), dict) else {}

    def extras(t: str) -> list:
        out = []
        low = t.lower()
        for raw, names in alts.items():
            if raw and str(raw).lower() in low and isinstance(names, list):
                out.extend(str(n) for n in names if n)
        return out[:4]

    async def one(t):
        try:
            return await asyncio.wait_for(xray_leg(t, slip.get("sport"), extras(t)), timeout=6)
        except Exception:
            log.warning("X-ray failed for %r", t, exc_info=True)
            return {"text": t, "values": [], "line": None, "side": None, "name": None, "stat": None,
                    "why": "couldn't load the game log"}
    return list(await asyncio.gather(*(one(t) for t in legs)))


def xray_hits(x: dict) -> Optional[tuple[int, int]]:
    if not x["values"] or x["line"] is None:
        return None
    vals = [v for _, _, v in x["values"]]
    good = sum(1 for v in vals if (v > x["line"] if x["side"] == "over" else v < x["line"]))
    return good, len(vals)


def line_suspect(x: dict) -> bool:
    """True when the line can't be what was on the slip: far below or above everything the player does."""
    vals = [v for _, _, v in (x.get("values") or [])]
    line = x.get("line")
    if not vals or line is None or line <= 0 or len(vals) < 3:
        return False
    avg, top = sum(vals) / len(vals), max(vals)
    if line > 3 * top + 1:
        return True                                     # Kyren "over 23" TDs when he's never had more than 2
    return line >= 1 and avg >= 8 * line and min(vals) > line and avg >= 15   # 4.6 against 90-yard games


def xray_notes(data: list[dict]) -> list[str]:
    notes = []
    for x in data:
        h = xray_hits(x)
        if h and line_suspect(x):
            vals = [v for _, _, v in x["values"]]
            notes.append(f"- {x['text']}: THIS LINE LOOKS MISREAD from the screenshot (avg {sum(vals) / len(vals):.1f} "
                         f"against a line of {x['line']:g}). Say the line looks wrong and to check the slip; don't rate it.")
            continue
        if h:
            vals = [v for _, _, v in x["values"]]
            src = f" · {x['sources']}" if x.get("sources") and x.get("sources") != "ESPN game log" else ""
            notes.append(f"- {x['text']}: last {h[1]} games {h[0]}/{h[1]} {x['side']} {x['line']:g} "
                         f"(avg {sum(vals) / len(vals):.1f}, most recent {', '.join(f'{v:g}' for v in vals[-5:][::-1])}){src}")
    return notes


def render_xray(title: str, data: list[dict], heading: str = "SLIP X-RAY",
                sport: Optional[str] = None) -> io.BytesIO:
    from PIL import Image, ImageDraw
    W, ROW, SHORT = 1000, 190, 96
    H = 120 + sum(ROW if xray_hits(x) else SHORT for x in data) + 50
    img, d = _design_card(W, H, design_sport_key(sport, *(x.get("stat") or x.get("text") for x in data)),
                          (70, 34, 150), head=150, margin=0, radius=0)
    d.text((36, 26), heading, font=art_font(40, True), fill=ART_TEXT)
    t, f = fit_text(d, title, W - 72, 20, False)
    d.text((38, 76), t, font=f, fill=ART_MUTED)
    y = 120
    for x in data:
        d.rounded_rectangle((20, y, W - 20, y + (ROW if xray_hits(x) else SHORT) - 14), 22, fill=(12, 12, 18, 190), outline=(255, 255, 255, 22))
        t, f = fit_text(d, x["text"], 330 if xray_hits(x) else 520, 22, True)
        d.text((44, y + 22), t, font=f, fill=ART_TEXT)
        h = xray_hits(x)
        if h is None:
            wt, wf = fit_text(d, x["why"] or "no data", 500, 17, False)
            d.text((W - 44 - _tw(d, wt, wf), y + 26), wt, font=wf, fill=ART_MUTED)
            y += SHORT
            continue
        good, n = h
        rate = good / n
        colour = ART_GREEN if rate >= 0.6 else ART_AMBER if rate >= 0.4 else ART_RED
        d.text((44, y + 58), f"{good}/{n}", font=art_font(52, True), fill=colour)
        vals = [v for _, _, v in x["values"]]
        d.text((44, y + 122), f"{x['side']} {x['line']:g}  ·  avg {sum(vals) / len(vals):.1f}", font=art_font(18, True),
               fill=ART_MUTED)
        # bars
        cx0, cx1, cy0, cy1 = 440, W - 44, y + 22, y + ROW - 52
        top = max(vals + [x["line"]]) * 1.15 or 1
        bw = (cx1 - cx0) / max(len(vals), 1)
        ly = cy1 - (x["line"] / top) * (cy1 - cy0)
        for dx in range(int(cx0), int(cx1), 14):
            d.line((dx, ly, dx + 7, ly), fill=(150, 150, 168), width=2)
        for k, (opp, at, v) in enumerate(x["values"]):
            good_game = v > x["line"] if x["side"] == "over" else v < x["line"]
            bx = cx0 + k * bw + bw * 0.18
            by = cy1 - (v / top) * (cy1 - cy0)
            d.rounded_rectangle((bx, min(by, cy1 - 3), bx + bw * 0.64, cy1), 6, fill=ART_GREEN if good_game else ART_RED)
            vf = art_font(15, True)
            vt = f"{v:g}"
            d.text((bx + bw * 0.32 - _tw(d, vt, vf) / 2, min(by, cy1 - 3) - 20), vt, font=vf, fill=ART_TEXT)
            of = art_font(13)
            ot = ("@" if at == "@" else "") + opp
            d.text((bx + bw * 0.32 - _tw(d, ot, of) / 2, cy1 + 6), ot, font=of, fill=ART_MUTED)
        lt = f"{x['line']:g}"
        lf = art_font(15, True)
        d.text((cx0 - 10 - _tw(d, lt, lf), ly - 9), lt, font=lf, fill=ART_TEXT)
        y += ROW
    d.text((36, H - 40), "Last 10 games, oldest → newest · green = beat the number", font=art_font(15), fill=ART_FAINT)
    brand_sign(img, W - 36, H - 40, "PIMP-BOT", 15, variant="cool")
    return _design_png(img)


async def slip_xray_file(slip: dict, data: Optional[list] = None) -> Optional[discord.File]:
    data = data if data is not None else await slip_xray_data(slip)
    if not any(xray_hits(x) for x in data):
        return None
    title = " · ".join(x for x in (slip.get("platform"), slip.get("description")) if x)
    png = await asyncio.to_thread(locked_render, render_xray, title, data, "SLIP X-RAY", slip.get("sport"))
    return discord.File(png, filename="xray.png")


# ---- ghost slips -------------------------------------------------------------------------------

def _ensure_r15_tables():
    db().executescript("""
        CREATE TABLE IF NOT EXISTS ghosts (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            guild_id    INTEGER NOT NULL,
            user_id     INTEGER NOT NULL,
            user_name   TEXT,
            draft_mid   INTEGER NOT NULL,
            channel_id  INTEGER,
            reply_mid   INTEGER,
            sport       TEXT,
            description TEXT,
            legs        TEXT NOT NULL,
            cost        REAL,
            payout      REAL,
            created_at  TEXT NOT NULL,
            checked_at  TEXT,
            result      TEXT NOT NULL DEFAULT 'open',
            settled_at  TEXT,
            UNIQUE (guild_id, draft_mid)
        );
        CREATE TABLE IF NOT EXISTS leg_pings (
            pick_id INTEGER NOT NULL,
            idx     INTEGER NOT NULL,
            state   TEXT NOT NULL,
            PRIMARY KEY (pick_id, idx, state)
        );
    """)
    db().commit()


_r15_ready = False


def r15_db():
    global _r15_ready
    if not _r15_ready:
        _ensure_r15_tables()
        _r15_ready = True
    return db()


def add_ghost(guild_id: int, poster_id: int, poster_name: str, draft_mid: int, channel_id: int,
              reply_mid: Optional[int], slip: dict) -> None:
    legs = [str(x).strip() for x in (slip.get("legs") or []) if str(x).strip()]
    if not legs:
        return
    r15_db().execute("""INSERT OR IGNORE INTO ghosts (guild_id, user_id, user_name, draft_mid, channel_id, reply_mid, sport,
                        description, legs, cost, payout, created_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
                     (guild_id, poster_id, poster_name, draft_mid, channel_id, reply_mid, slip.get("sport"),
                      str(slip.get("description") or "Slip")[:200],
                      json.dumps([{"idx": k, "text": t, "status": "open"} for k, t in enumerate(legs, 1)]),
                      slip.get("cost"), slip.get("payout"), now_iso()))
    db().commit()


def clear_matching_ghosts(guild_id: int, user_id: int, legs_text: Optional[str]) -> None:
    """They played it after all (logged by any route): drop open ghosts sharing at least half their legs."""
    mine = {norm_name(x) for x in (legs_text or "").splitlines() if x.strip()}
    if not mine:
        return
    for g in r15_db().execute("SELECT id, legs FROM ghosts WHERE guild_id = ? AND user_id = ? AND result = 'open'",
                              (guild_id, user_id)).fetchall():
        theirs = {norm_name(x["text"]) for x in json.loads(g["legs"])}
        if theirs and len(mine & theirs) * 2 >= len(theirs):
            db().execute("DELETE FROM ghosts WHERE id = ?", (g["id"],))
    db().commit()


def drop_ghost(guild_id: int, draft_mid: int) -> None:
    r15_db().execute("DELETE FROM ghosts WHERE guild_id = ? AND draft_mid = ? AND result = 'open'", (guild_id, draft_mid))
    db().commit()


def leg_outcome(e: dict) -> Optional[str]:
    """hit / miss / push once a leg is decided (an over that's cleared counts), else None."""
    if e.get("status") in ("hit", "miss", "push"):
        return e["status"]
    if e.get("live") in ("hit", "miss", "push"):
        return e["live"]
    if e.get("final") in ("hit", "miss", "push"):
        return e["final"]
    ev = e.get("event") or {}
    if (ev.get("final") or ev.get("state") == "post") and e.get("live") in ("ahead", "behind"):
        return "hit" if e["live"] == "ahead" else "miss"
    return None


GHOST_DAYS = 4


async def grade_ghosts(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    rows = r15_db().execute("SELECT * FROM ghosts WHERE result = 'open' AND (checked_at IS NULL OR checked_at < ?) "
                            "ORDER BY checked_at LIMIT 10", (iso(now - timedelta(minutes=8)),)).fetchall()
    for g in rows:
        db().execute("UPDATE ghosts SET checked_at = ? WHERE id = ?", (now_iso(), g["id"]))
        db().commit()
        if datetime.fromisoformat(g["created_at"]) < now - timedelta(days=GHOST_DAYS):
            db().execute("UPDATE ghosts SET result = 'expired', settled_at = ? WHERE id = ?", (now_iso(), g["id"]))
            db().commit()
            continue
        legs = json.loads(g["legs"])
        pseudo = {"id": -g["id"], "sport": g["sport"], "description": g["description"], "status": "open",
                  "created_at": g["created_at"]}
        try:
            entries = await leg_progress(pseudo, legs=legs)
        except Exception:
            log.warning("Ghost %s check failed", g["id"], exc_info=True)
            continue
        for leg, e in zip(legs, entries):
            got = leg_outcome(e)
            if got:
                leg["status"] = got
                if e.get("num") and e["num"].get("value") is not None:
                    leg["value"] = e["num"]["value"]
        db().execute("UPDATE ghosts SET legs = ? WHERE id = ?", (json.dumps(legs), g["id"]))
        db().commit()
        states = [x["status"] for x in legs]
        if "miss" in states:
            result = "miss"
        elif all(s in ("hit", "push") for s in states) and "hit" in states:
            result = "hit"
        else:
            continue
        db().execute("UPDATE ghosts SET result = ?, settled_at = ? WHERE id = ?", (result, now_iso(), g["id"]))
        db().commit()
        await announce_ghost(client, g, legs, result)


def ghost_line(g, legs: list, result: str) -> str:
    who = g["user_name"] or "you"
    if result == "hit":
        amt = f" ({signed(g['payout'] - g['cost'])})" if g["cost"] and g["payout"] else ""
        return (f"👻 **Ghost slip:** {who} passed on {clip(g['description'], 60)}, and it would've **hit**{amt}. 🫠 "
                f"Every leg came in.")
    miss = next((x for x in legs if x["status"] == "miss"), None)
    tail = f" {clip(miss['text'], 70)}" + (f" ({miss['value']:g})" if miss and miss.get("value") is not None else "") + \
           " sank it." if miss else ""
    return f"👻 **Ghost slip:** good pass, {who}. {clip(g['description'], 60)} would've **missed**.{tail}"


async def announce_ghost(client, g, legs: list, result: str) -> None:
    line = ghost_line(g, legs, result)
    channel = client.get_channel(g["channel_id"]) if g["channel_id"] else None
    if channel is None:
        return
    try:
        if g["reply_mid"]:
            ref = channel.get_partial_message(g["reply_mid"])
            ref = ref.to_reference(fail_if_not_exists=False) if hasattr(ref, "to_reference") else ref
            await channel.send(line, reference=ref, mention_author=False, allowed_mentions=discord.AllowedMentions.none())
        else:
            await channel.send(line, allowed_mentions=discord.AllowedMentions.none())
    except Exception:
        log.warning("Couldn't post ghost result %s", g["id"], exc_info=True)


def pass_record(guild_id: int, user_id: int) -> dict:
    rows = r15_db().execute("SELECT * FROM ghosts WHERE guild_id = ? AND user_id = ? AND result IN ('hit', 'miss') "
                            "ORDER BY settled_at DESC", (guild_id, user_id)).fetchall()
    good = [r for r in rows if r["result"] == "miss"]
    bad = [r for r in rows if r["result"] == "hit"]
    saved = sum(r["cost"] or 0 for r in good)
    missed = sum((r["payout"] or 0) - (r["cost"] or 0) for r in bad)
    open_n = r15_db().execute("SELECT COUNT(*) AS n FROM ghosts WHERE guild_id = ? AND user_id = ? AND result = 'open'",
                              (guild_id, user_id)).fetchone()["n"]
    return {"good": len(good), "bad": len(bad), "saved": saved, "missed": missed, "open": open_n, "rows": rows[:6]}


# ---- leg-by-leg DMs + sweat radio ------------------------------------------------------------------

_LEG_SEEN: dict[int, float] = {}


def leg_label(text: str) -> str:
    pr = cached_prop(text)
    if pr:
        return pr["display"].split()[-1] if len(pr["display"].split()) > 1 else pr["display"]
    return clip(text, 30)


async def leg_watch(client: discord.Client, now: Optional[datetime] = None) -> None:
    now = now or datetime.now(timezone.utc)
    r15_db()
    init = get_setting(0, "legwatch_init")
    if init is None:
        init = now_iso()
        set_setting(0, "legwatch_init", init)
    cutoff = iso(now - timedelta(days=3))
    recent = iso(now - timedelta(minutes=20))
    picks = db().execute("""SELECT * FROM picks WHERE (status = 'open' OR (settled_at >= ? AND id IN
                            (SELECT pick_id FROM leg_pings WHERE idx = 0))) AND created_at >= ?
                            AND bettor_id IS NOT NULL AND id IN (SELECT pick_id FROM legs)
                            ORDER BY id DESC LIMIT 60""", (recent, cutoff)).fetchall()
    spoken: dict[int, int] = {}
    said: set = set()
    checked = 0
    for p in picks:
        if checked >= 25:
            break
        if _LEG_SEEN.get(p["id"], 0) > time.monotonic() - 200:
            continue
        _LEG_SEEN[p["id"]] = time.monotonic()
        checked += 1
        entries = await cached_progress(p)
        sent = {(r["idx"], r["state"]) for r in db().execute("SELECT idx, state FROM leg_pings WHERE pick_id = ?", (p["id"],))}
        # picks that were already open when this feature arrived: record where they stand, don't DM about the past
        baseline = (0, "seen") not in sent and p["created_at"] <= init
        db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?, 0, 'seen')", (p["id"],))
        news, voice_lines = [], []
        for e in entries:
            out = leg_outcome(e)
            n = e.get("n")
            if out in ("hit", "miss") and (n, out) not in sent:
                db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?,?,?)", (p["id"], n, out))
                val = (e.get("num") or {}).get("value")
                news.append(("✅" if out == "hit" else "💀") + f" {clip(e['text'], 80)}: "
                            + ("cleared" if out == "hit" else "dead") + (f" ({val:g})" if val is not None else ""))
                voice_lines.append(f"{leg_label(e['text'])} clears for {p['bettor_name']}!" if out == "hit" else
                                   f"Ouch. {leg_label(e['text'])} is dead for {p['bettor_name']}.")
            num = e.get("num")
            if (out is None and num and num.get("side") == "over" and e.get("in_play") and num["line"] >= 1.5
                    and 0 < num["value"] < num["line"] and num["line"] - num["value"] <= max(1.0, num["line"] * 0.15)
                    and (n, "close") not in sent):
                db().execute("INSERT OR IGNORE INTO leg_pings (pick_id, idx, state) VALUES (?,?,?)", (p["id"], n, "close"))
                need = num["line"] - num["value"]
                voice_lines.append(f"{leg_label(e['text'])} is at {num['value']:g}. {p['bettor_name']} needs "
                                   f"{math.ceil(need) if need > 0.5 else 1} more.")
        db().commit()
        if baseline or (not news and not voice_lines):
            continue
        if news and get_setting(p["guild_id"], f"legalerts:{p['bettor_id']}") != "off" \
                and not is_quiet(p["guild_id"], p["bettor_id"], now):
            alive = sum(1 for e in entries if leg_outcome(e) != "miss")
            hits = sum(1 for e in entries if leg_outcome(e) == "hit")
            tail = (f"\n-# {hits}/{len(entries)} in" + ("" if alive == len(entries) else " · slip's dead") +
                    " · `/me legalerts` turns these off")
            try:
                user = await known_user(client, p["bettor_id"])
                user = user or await client.fetch_user(p["bettor_id"])
                for chunk in split_message(f"🎯 **{clip(p['description'], 60)}** (`#{p['id']}`)\n" + "\n".join(news) + tail):
                    await user.send(chunk)
            except Exception:
                log.info("Couldn't DM leg alert for pick %s", p["id"])
        if voice_lines and not p["hidden"] and p["guild_id"] in VOICE:
            for line in voice_lines:
                if spoken.get(p["guild_id"], 0) >= 4:
                    break
                if (p["guild_id"], line) in said:
                    continue
                said.add((p["guild_id"], line))
                spoken[p["guild_id"]] = spoken.get(p["guild_id"], 0) + 1
                await voice_say(client, p["guild_id"], line)
    if len(_LEG_SEEN) > 2000:
        _LEG_SEEN.clear()


# ==========================================================================
# r17: typed slips, "how's my slip?", /scout, posters, job health
# ==========================================================================

# ---- typed slips --------------------------------------------------------------------------------

LEGLIKE = re.compile(r"\b(?:over|under|more|less)\s?\d|\b[ou]\s?\d+\.5\b|\b\d+(?:\.\d+)?\s*\+(?!\d)"
                     r"|\b(?:ml|moneyline)\b|(?<![\w.$])[+-]\d{1,2}(?:\.5)?\b(?!\d)|\banytime\b", re.I)   # spreads, not -110 odds
TEXT_LOG = re.compile(r"^\s*(?:log|add|track(?! record)|record(?! of| with| on)|save|placed|played|locked in|i'?m on|im on|"
                      r"in on|tailing)\b", re.I)
TEXT_AMOUNT = re.compile(r"\$\s?\d|\bto (?:win|pay)\b", re.I)
QUESTION_START = re.compile(r"^\s*(?:who|what|whats|what's|when|where|why|which|is|are|does|do|did|can|could|odds|"
                            r"how many|how much|anyone|any)\b", re.I)
REVIEW_ASK = re.compile(r"\b(?:thoughts|rate (?:it|this|my)|review|break (?:it |this )?down|breakdown|what do (?:you|u|y'?all) think|"
                        r"should i (?:play|take|ride|tail|run)|would you (?:play|take|ride)|any good)\b", re.I)
STATUS_ASK = re.compile(r"\b(?:how(?:'s| is| are)|hows|where(?:'s| is| are)|update on|check(?: on)?)\b[^?]{0,25}\bmy\b"
                        r"[^?]{0,12}\b(?:slips?|parlays?|picks?|bets?|entries|entry|legs?)\b"
                        r"|\bmy\s+(?:slips?|parlays?|picks?|bets?)\s+(?:doing|looking|going|at)\b", re.I)
STATUS_NOT_NOW = re.compile(r"\b(?:season|year|month|week|record|rate|rank(?:ed)?|roi|profit|vs|versus|from|last|since|"
                            r"all[- ]time|leaderboard|history|overall|lifetime)\b", re.I)


def leg_hits(text: str) -> int:
    return len(LEGLIKE.findall(text))


def text_route(words: str) -> Optional[str]:
    """'status', 'log', 'review' or None (an ordinary question for the Q&A path)."""
    if STATUS_ASK.search(words) and not STATUS_NOT_NOW.search(words):
        return "status"
    hits = leg_hits(words)
    if not hits or len(words) < 6:
        return None
    if TEXT_LOG.search(words):
        return "log"
    question = bool(QUESTION_START.search(words)) or "?" in words
    if REVIEW_ASK.search(words) and (hits >= 2 or not QUESTION_START.search(words)):
        return "review"
    if TEXT_AMOUNT.search(words) and not question:
        return "log"
    if hits >= 2 and question and not QUESTION_START.search(words):
        return "review"
    return None
PLATFORM_WORDS = [(r"\bprize ?picks\b", "PrizePicks"), (r"\bkalshi\b", "Kalshi"), (r"\bunderdog\b", "Underdog"),
                  (r"\bdraft ?kings\b", "DraftKings"), (r"\bfan ?duel\b", "FanDuel")]
PLATFORM_ABBR = {"pp": "PrizePicks", "ud": "Underdog", "dk": "DraftKings", "fd": "FanDuel"}
PLATFORM_ABBR_RE = re.compile(r"(?:\b(?:on|via)\s+|@\s*)(pp|ud|dk|fd)\b|(?:,|^)\s*(pp|ud|dk|fd)\s*[,:]|\b(pp|ud|dk|fd)\s*$",
                              re.I)

TEXT_SLIP_PROMPT = """A member of a sports betting group typed a bet into Discord. Turn it into a slip.

Their message: <<<{text}>>>

Reply with ONLY a JSON object, no other text:
{{"is_slip": true or false, "platform": "PrizePicks" | "Kalshi" | a sportsbook name | "Other",
  "sport": short sport/league name or null, "description": one short line like "3-pick Power Play" or "2-leg parlay",
  "legs": ["one string per leg, written out in full: 'Player Name over|under LINE stat' (o/More = over, u/Less = \
under; '22.5+' = over 22.5), or 'Team ML', 'Team -3.5', 'Over 44.5'. Expand common nicknames to full names."],
  "cost": amount risked or null if not given, "payout": total paid back if it wins or null if not given}}
"$10 to win $30" means cost 10, payout 30. Numbers must be plain numbers. Never invent an amount."""


def text_slip_words(message) -> str:
    return re.sub(r"<@[!&]?\d+>", " ", getattr(message, "content", "") or "").strip()


def looks_like_legs(text: str) -> bool:
    return len(text) >= 6 and bool(LEGLIKE.search(text))


def parse_text_slip(text: str) -> Optional[dict]:
    """No-Claude fallback: legs split on new lines, commas, semicolons or ' + '; '$10 to win $30' amounts."""
    t = text
    cost = payout = None
    amt = r"(?<![\d,.])(\d{1,3}(?:,\d{3})+(?:\.\d+)?|\d+(?:\.\d+)?)"
    m = (re.search(r"(?:\$\s*)?" + amt + r"\s*(?:to win|to pay|pays|->|→)\s*\$?\s*" + amt, t, re.I)
         or re.search(r"\$\s*" + amt + r"\s*/\s*\$?\s*" + amt, t))
    if m:
        cost, payout = as_amount(m.group(1)), as_amount(m.group(2))
        t = t.replace(m.group(0), " ")
    else:
        m = re.search(r"(?:\bfor\s+|\brisk(?:ing)?\s+)?\$\s*" + amt, t, re.I)
        if m:
            cost = as_amount(m.group(1))
            t = t.replace(m.group(0), " ")
    platform = "Other"
    for pat, name in PLATFORM_WORDS:
        hit = re.search(pat, t, re.I)
        if hit:
            platform = name
            t = t[:hit.start()] + " " + t[hit.end():]
            break
    else:
        hit = PLATFORM_ABBR_RE.search(t)
        if hit:
            platform = PLATFORM_ABBR[(hit.group(1) or hit.group(2) or hit.group(3)).lower()]
            t = t[:hit.start()] + " , " + t[hit.end():]
    t = TEXT_LOG.sub(" ", t)
    t = re.sub(r"\b(this|these|for me|please|pls|slip|parlay|my|on)\b", " ", t, flags=re.I)
    parts, glue = [], False
    for k, bit in enumerate(re.split(r"(\n|;|,|\s\+\s|\s&\s|\s+and\s+)", t)):
        if k % 2:      # a separator: " + " right after a bare name is a two-player combo, not a new leg
            glue = bit.strip() == "+" and bool(parts) and not LEGLIKE.search(parts[-1])
            continue
        bit = bit.strip(" -–•*:")
        if bit and glue:
            parts[-1] += " + " + bit
        elif bit:
            parts.append(bit)
        glue = False
    legs = []
    for p in parts:
        if not LEGLIKE.search(p):
            continue
        p = re.sub(r"(?i)\bo\s?(\d+(?:\.\d+)?)\b", r"over \1", p)
        p = re.sub(r"(?i)\bu\s?(\d+(?:\.\d+)?)\b", r"under \1", p)
        legs.append(" ".join(p.split()))
    if not legs:
        return None
    legs = legs[:20]
    return {"is_slip": True, "platform": platform, "sport": None,
            "description": f"{len(legs)}-leg slip" if len(legs) > 1 else "Single", "legs": legs, "cost": cost,
            "payout": payout, "returned": None, "status": "open", "placed": True}


async def read_text_slip(text: str) -> tuple[Optional[dict], Optional[str]]:
    if not ai_enabled():
        slip = parse_text_slip(text)
        return slip, None if slip else "I couldn't find any legs in that"
    try:
        reply = await asyncio.wait_for(anthropic_client().messages.create(
            model=CLAUDE_MODEL, max_tokens=800,
            messages=[{"role": "user", "content": TEXT_SLIP_PROMPT.format(text=text[:1500])}]), timeout=25)
        slip = extract_json("".join(b.text for b in reply.content if getattr(b, "type", "") == "text"))
    except Exception as exc:
        log.warning("Typed slip read failed; using the simple parser", exc_info=True)
        slip = parse_text_slip(text)
        return slip, None if slip else explain_ai_error(exc)[0]
    if not slip.get("is_slip") or not slip.get("legs"):
        return None, "not_slip"
    legs = slip["legs"]
    if isinstance(legs, str):
        legs = [x for x in re.split(r"\n|;", legs)]
    slip["legs"] = [str(x).strip() for x in legs if str(x).strip()][:20]
    if not slip["legs"]:
        return None, "not_slip"
    slip["cost"] = as_amount(slip.get("cost"))
    slip["payout"] = as_amount(slip.get("payout"))
    slip.update(returned=None, status="open", placed=True)
    return slip, None


def slip_draft_embed(slip: dict, title: str = "🧾 Log this slip?") -> discord.Embed:
    legs = [str(x) for x in slip.get("legs") or []]
    e = discord.Embed(title=title, color=BRAND,
                      description=clip("\n".join(f"`{k}` {leg}" for k, leg in enumerate(legs, 1)), 3500) or "No legs")
    e.add_field(name="Platform", value=str(slip.get("platform") or "Other")[:40])
    e.add_field(name="Play", value=clip(str(slip.get("description") or "Slip"), 100))
    if slip.get("cost"):
        e.add_field(name="Riding", value=f"{money(slip['cost'])} → {money(slip['payout'] or 0)}" +
                    ("" if slip.get("payout") else " (payout missing: tap ✏️ Edit)"))
    else:
        e.add_field(name="Riding", value="Amounts missing: tap ✏️ Edit")
    e.set_footer(text="Nothing's logged until you tap ✅ Log it.")
    return e


class DraftEditModal(discord.ui.Modal, title="Edit before logging"):
    platform = discord.ui.TextInput(label="Platform", max_length=40)
    description = discord.ui.TextInput(label="The play", max_length=200)
    legs = discord.ui.TextInput(label="Legs (one per line)", style=discord.TextStyle.paragraph, max_length=900)
    cost = discord.ui.TextInput(label="Cost / entry", max_length=12)
    payout = discord.ui.TextInput(label="Pays if it wins", max_length=12)

    def __init__(self, message_id: int, d: dict):
        super().__init__()
        self.message_id = message_id
        slip = d["slip"]
        self.platform.default = str(slip.get("platform") or "Other")[:40]
        self.description.default = str(slip.get("description") or "Slip")[:200]
        self.legs.default = "\n".join(str(x) for x in slip.get("legs") or [])[:900]
        self.cost.default = f"{slip['cost']:.2f}" if slip.get("cost") is not None else None
        self.payout.default = f"{slip['payout']:.2f}" if slip.get("payout") is not None else None

    async def on_submit(self, interaction: discord.Interaction):
        d = get_slip_draft(interaction.guild_id, self.message_id)
        if d is None or interaction.user.id != d["poster"] or d.get("used"):
            await interaction.response.send_message("That slip isn't yours to log, or it's already logged.", ephemeral=True)
            return
        try:
            cost, payout = parse_money(self.cost.value), parse_money(self.payout.value)
        except ValueError:
            await interaction.response.send_message("Cost and payout need to be amounts, like 10 or $10.", ephemeral=True)
            return
        if cost <= 0:
            await interaction.response.send_message("Cost has to be more than 0.", ephemeral=True)
            return
        until = cooling_until(interaction.guild_id, interaction.user.id)
        if until:
            await interaction.response.send_message(cooloff_message(until), ephemeral=True)
            return
        legs = [x.strip() for x in self.legs.value.splitlines() if x.strip()]
        old_legs = list(d["slip"].get("legs") or [])
        remember_scan_edits(old_legs, legs)
        for old, new in zip(old_legs, legs):
            if old.strip() and old.strip() != new.strip():
                staff_log_add(interaction.guild_id, "edit", f"Edit kept the old line: {clip(old, 140)}",
                              getattr(interaction.user, "display_name", "") or "")
                break
        d["slip"].update(platform=self.platform.value.strip() or "Other", description=self.description.value.strip() or "Slip",
                         legs=legs, cost=cost, payout=payout, placed=True)
        d["used"] = -1
        set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
        await interaction.response.defer()

        async def reply(**kw):
            return await interaction.followup.send(wait=True, **kw)
        bettor = None
        if can_file_for_others(interaction.user, interaction.guild_id) and d.get("for_id"):
            bettor = _FiledWho(int(d["for_id"]), d.get("for_name") or "them")
        try:
            pid = await interaction.client.log_parsed_slip(interaction.guild_id, interaction.user, interaction.channel,
                                                           d["slip"], d["url"], reply, bettor=bettor,
                                                           shot_message_id=self.message_id)
        except Exception:
            log.exception("Logging an edited draft failed")
            d["used"] = None
            set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
            await interaction.followup.send("⚠️ Something went wrong logging that. Try ✏️ Edit again.", ephemeral=True)
            return
        d["used"] = pid
        set_setting(interaction.guild_id, f"draft:{self.message_id}", json.dumps(d))
        drop_ghost(interaction.guild_id, self.message_id)


# ---- "how's my slip doing?" -------------------------------------------------------------------------

async def slip_status_files(client, guild_id: int, user_id: int, limit: int = 3) -> tuple[list, int]:
    cutoff = iso(datetime.now(timezone.utc) - timedelta(days=4))
    picks = db().execute("SELECT * FROM picks WHERE guild_id = ? AND bettor_id = ? AND status = 'open' AND created_at >= ? "
                         "AND (hidden IS NULL OR hidden = 0) ORDER BY id DESC", (guild_id, user_id, cutoff)).fetchall()
    files = []
    for p in picks[:limit]:
        try:
            files.append(await receipt_file(client, p))
        except Exception:
            log.warning("Status receipt failed for pick %s", p["id"], exc_info=True)
    return files, len(picks)


# ---- /scout ----------------------------------------------------------------------------------------

async def scout_data(cand: dict, stat: Optional[str] = None, line: Optional[float] = None) -> tuple[list, list]:
    """(X-ray rows for the player's main stats, the raw games)."""
    fam = FAMILY_OF_PATH[cand["path"]]
    games = await trend_games(cand["path"], cand["id"], need=10)
    keys = [stat] if stat else [k for k in MAIN_STATS.get(fam, []) if k in STATS and k != "minutes"]
    rows = []
    for k in keys:
        vals = trend_values(games, k)[:10]
        if not vals or (not stat and sum(v for _, v in vals) == 0):
            continue
        ln = float(line) if (stat and line is not None) else default_line([v for _, v in vals])
        rows.append({"text": f"{STATS[k][0]} · line {ln:g}", "values": [(g["opp"], g["at"], v) for g, v in vals][::-1],
                     "line": ln, "side": "over", "name": cand["name"], "stat": STATS[k][0], "why": "", "key": k})
    return rows[:4], games


# ---- posters ----------------------------------------------------------------------------------------

POSTER_TITLE = 46
POSTER_SUB = 22


def render_cashed_poster(title: str, sub: str, receipts: list[io.BytesIO]) -> io.BytesIO:
    from PIL import Image, ImageDraw
    thumbs = []
    for r in receipts[:6]:
        r.seek(0)
        im = Image.open(r).convert("RGB")
        w = 470
        thumbs.append(im.resize((w, int(im.height * w / im.width)), Image.LANCZOS))
    cols = 2 if len(thumbs) > 1 else 1
    W = 40 + cols * 470 + (cols - 1) * 20 + 40
    col_h = [0] * cols
    places = []
    for t in thumbs:
        c = col_h.index(min(col_h))
        places.append((c, col_h[c]))
        col_h[c] += t.height + 20
    H = 190 + max(col_h or [0]) + 40
    img, d = _design_card(W, H, "stadium", (20, 120, 80), (90, 230, 160), head=200, margin=0, radius=0)
    t, f = fit_text(d, title, W - 80, POSTER_TITLE, True)
    d.text((40, 36), t, font=f, fill=ART_TEXT)
    d.text((42, 104), sub, font=art_font(POSTER_SUB, True), fill=ART_GREEN)
    for th, (c, y) in zip(thumbs, places):
        d.rounded_rectangle((34 + c * 490, 174 + y, 46 + c * 490 + th.width, 186 + y + th.height), 34,
                            fill=(0, 0, 0, 110))
        img.paste(th, (40 + c * 490, 180 + y))
    brand_sign(img, W - 40, H - 34, "PIMP-BOT", 15, variant="hype")
    return _design_png(img)


def render_standings_poster(title: str, sub: str, rows: list[dict]) -> io.BytesIO:
    """rows: rank, name, avatar, record, net, roi, move"""
    from PIL import Image, ImageDraw
    W, RH = 900, 92
    rows = rows[:12]
    H = 210 + RH * len(rows) + 50
    img, d = _design_card(W, H, "stadium", (150, 110, 20), (255, 214, 102), head=210, margin=0, radius=0)
    t, f = fit_text(d, title, W - 80, POSTER_TITLE, True)
    d.text((40, 36), t, font=f, fill=ART_TEXT)
    d.text((42, 104), sub, font=art_font(POSTER_SUB, True), fill=ART_MUTED)
    medal = {1: (255, 214, 102), 2: (210, 216, 226), 3: (214, 150, 90)}
    y = 205
    for r in rows:
        d.rounded_rectangle((24, y, W - 24, y + RH - 12), 20, fill=(12, 12, 18, 190) if r["rank"] > 3 else (40, 34, 20, 206),
                            outline=(255, 255, 255, 22) if r["rank"] > 3 else medal[r["rank"]] + (120,))
        rc = medal.get(r["rank"], ART_MUTED)
        rt = str(r["rank"])
        d.text((70 - _tw(d, rt, art_font(32, True)) / 2, y + 18), rt, font=art_font(32, True), fill=rc)
        av = _avatar(r.get("avatar"), 58, r["name"], -1)
        img.paste(av, (110, y + 11), av)
        t, f = fit_text(d, r["name"], 300, 28, True)
        d.text((186, y + 12), t, font=f, fill=ART_TEXT)
        d.text((188, y + 48), r["record"], font=art_font(18, True), fill=ART_MUTED)
        mv = r.get("move") or 0
        if mv:
            arrow = ("▲" if mv > 0 else "▼") + str(abs(mv))
            d.text((W - 330, y + 26), arrow, font=art_font(22, True), fill=ART_GREEN if mv > 0 else ART_RED)
        net = signed_short(r["net"])
        t, f = fit_text(d, net, 200, 30, True)
        d.text((W - 56 - _tw(d, t, f), y + 12), t, font=f, fill=ART_GREEN if r["net"] >= 0 else ART_RED)
        roi = f"{r['roi']:+.0f}% ROI"
        d.text((W - 56 - _tw(d, roi, art_font(17, True)), y + 50), roi, font=art_font(17, True), fill=ART_MUTED)
        y += RH
    brand_sign(img, W - 40, H - 36, "PIMP-BOT", 15, variant="crown")
    return _design_png(img)


async def cashed_poster_file(client, guild_id: int, days: int = 7) -> Optional[discord.File]:
    since = iso(datetime.now(timezone.utc) - timedelta(days=days))
    wins = db().execute("SELECT * FROM picks WHERE guild_id = ? AND status = 'win' AND settled_at >= ? AND "
                        "(hidden IS NULL OR hidden = 0 OR revealed_at IS NOT NULL)", (guild_id, since)).fetchall()
    wins = sorted(wins, key=pick_net, reverse=True)[:6]
    if not wins:
        return None
    receipts = []
    for p in wins:
        user = (await known_user(client, p["bettor_id"]) if p["bettor_id"] else None)
        av = await avatar_bytes(user) if user else None
        receipts.append(await asyncio.to_thread(locked_render, render_receipt, receipt_data(p, db_entries(p), av)))
    total = sum(pick_net(p) for p in wins)
    png = await asyncio.to_thread(locked_render, render_cashed_poster, "CASHED THIS WEEK" if days == 7 else
                                  f"CASHED · LAST {days} DAYS", f"{signed_short(total)} across {len(wins)} slip"
                                  f"{'s' if len(wins) != 1 else ''}", receipts)
    return discord.File(png, filename="cashed.png")


async def standings_poster_file(client, guild_id: int, period: str = "season", back: bool = False) -> Optional[discord.File]:
    now = datetime.now(timezone.utc)
    until = None
    since = None if period == "season" else iso(now - timedelta(days=7 if period == "week" else 30))
    season = current_season(guild_id) if period == "season" else None
    if season is not None:
        since = season["started_at"]
    if period == "month" and back:
        since = iso(now - timedelta(days=60))
        until = iso(now - timedelta(days=30))
        season = None
    stats = [s for s in compute_stats(guild_id, since=since, until=until) if s["wins"] + s["losses"] + s["pushes"] > 0]
    if not stats:
        return None
    moves = rank_movement(guild_id, [s["key"] for s in stats], since, None) if period == "season" else {}
    top = stats[:12]
    users = [(await known_user(client, int(s["key"])) if s["key"].isdigit() else None) for s in top]

    async def av(u):
        return await avatar_bytes(u) if u else None
    avatars = await asyncio.gather(*(av(u) for u in users))
    rows = [{"rank": k, "name": s["name"], "avatar": a, "record": record_line(s), "net": s["net"], "roi": s["roi"],
             "move": moves.get(s["key"], 0)} for k, (s, a) in enumerate(zip(top, avatars), 1)]
    label = {"season": f"{season['name'].upper()} STANDINGS" if season is not None else "ALL-TIME STANDINGS",
             "week": "THIS WEEK", "month": "PREVIOUS MONTH" if back else "LAST 30 DAYS"}[period]
    png = await asyncio.to_thread(locked_render, render_standings_poster, label,
                                  datetime.now(TZ).strftime("%b %-d, %Y"), rows)
    return discord.File(png, filename="standings.png")


# ---- background job health -----------------------------------------------------------------------------

JOB_HEALTH: dict[str, dict] = {}
JOB_ALERT_AFTER = 5


def job_name(job) -> str:
    name = getattr(job, "__name__", "job")
    if name == "<lambda>":
        names = [n for n in getattr(getattr(job, "__code__", None), "co_names", ()) if n not in ("astimezone",)]
        return names[0] if names else "job"
    return name


def job_recently_clean(name: str, within: float = 90) -> bool:
    """True when this job finished with no error a moment ago, so this cycle can leave it alone."""
    h = JOB_HEALTH.get(name)
    if not h or h.get("fails") or not h.get("ok_at"):
        return False
    try:
        age = (datetime.now(timezone.utc) - datetime.fromisoformat(h["ok_at"])).total_seconds()
    except (TypeError, ValueError):
        return False
    return 0 <= age < within


def record_job(name: str, error: Optional[BaseException]) -> Optional[str]:
    """Track a run; returns an alert line the first time a job has failed JOB_ALERT_AFTER times in a row."""
    h = JOB_HEALTH.setdefault(name, {"fails": 0, "last_error": None, "alerted": False, "ok_at": None})
    if error is None:
        recovered = h["alerted"]
        h.update(fails=0, ok_at=now_iso(), alerted=False)
        return f"✅ Background job `{name}` is working again." if recovered else None
    h["fails"] += 1
    h["last_error"] = sec_redact(f"{type(error).__name__}: {error}")[:200]
    if h["fails"] >= JOB_ALERT_AFTER and not h["alerted"]:
        h["alerted"] = True
        return (f"⚠️ Background job `{name}` has failed {h['fails']} times in a row: `{h['last_error']}`. "
                "Everything else keeps running; Railway's logs have the details.")
    return None


def job_health_line() -> str:
    bad = {k: v for k, v in JOB_HEALTH.items() if v["fails"]}
    if not JOB_HEALTH:
        return "not run yet"
    if not bad:
        return f"✅ all {len(JOB_HEALTH)} healthy"
    return "⚠️ " + " · ".join(f"`{k}` failing ×{v['fails']}" for k, v in list(bad.items())[:5])


